/* Call only for terrain polygons of gState.mapNum==11. Not a sprite classifier. */
static const VH_Map02Texture *VH_Map02Find(int tpage, int clut, int u, int v) {
    int i;
    for (i=0; i<VH_MAP02_HD_SLOT_COUNT; ++i) {
        const VH_Map02Texture *r=&vh_map02_hd_slots[i];
        if (r->tpage == tpage && r->clut == clut && u >= r->u && v >= r->v &&
            u < r->u+r->w && v < r->v+r->h) return r;
    }
    return 0;
}

/* Integer *high-resolution pixel* -> integer canonical-master pixel.
 * Slots are canonical rotated CCW, then flipped horizontally. This is the inverse.
 * Must preserve scale in pixel-space (e.g. scale=4), not downsample to original UV.
 * Returns 0 on invalid coordinates. */
static int VH_Map02ToMaster(const VH_Map02Texture *r, int scale, int x, int y,
                           int *master_x, int *master_y) {
    int sw, sh, cw, ch;
    if (!r || !master_x || !master_y || scale <= 0 || scale > 32) return 0;
    sw=r->w*scale; sh=r->h*scale;
    cw=r->canonical_w*scale; ch=r->canonical_h*scale;
    if (x < 0 || y < 0 || x >= sw || y >= sh) return 0;
    if (r->mirror_lr) x=sw-1-x;
    switch (r->turns_ccw) {
    case 0: *master_x=x; *master_y=y; break;
    case 1: *master_x=cw-1-y; *master_y=x; break;
    case 2: *master_x=cw-1-x; *master_y=ch-1-y; break;
    case 3: *master_x=y; *master_y=ch-1-x; break;
    default: return 0;
    }
    return *master_x>=0 && *master_x<cw && *master_y>=0 && *master_y<ch;
}

